import {applyAdSizing} from './advertising-public.mjs';
import {landingHTML,infoHTML,previewCampaign} from './public-layout.mjs';
import {initHowItWorks} from './how-it-works.mjs';
import {discoverIntro,discoverCommunity,discoveryCard} from './discover-design.mjs';
const stage=document.querySelector('#preview-stage');let snapshot,model,selected;
const labels={'home-top':'Đầu trang chủ','home-bottom':'Cuối trang chủ','explore-sidebar':'Bên cạnh Khám phá','explore-content':'Trong nội dung Khám phá','community-banner':'Cộng đồng','how-it-works-banner':'Cách hoạt động','footer-banner':'Chân trang'};
const pages={home:['home-top','home-bottom','footer-banner'],explore:['explore-sidebar','explore-content','community-banner','footer-banner'],community:['community-banner','footer-banner'],'how-it-works':['how-it-works-banner','footer-banner'],info:['footer-banner']};
function send(type,extra={}){if(window.parent!==window)window.parent.postMessage({type,...extra},location.origin);}
function zone(id){const el=document.createElement('section');el.className='ad-zone ad-preview-zone';el.dataset.adZone=id;el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label','Chọn vị trí '+labels[id]);el.draggable=false;const label=document.createElement('small');label.textContent=labels[id]+' · Quảng cáo';el.append(label);const placement=(model.placements||[]).find(p=>p.id===id&&(!p.device||p.device===model.device));const campaigns=model.campaigns||[];const campaign=previewCampaign({placements:model.placements||[],campaigns,zoneId:id,device:model.device});const fields=campaign?.draft||campaign?.live||campaign;const creative=(model.creatives||[]).find(c=>c.id===fields?.creativeId);
 if(creative&&fields?.type!=='adsense'){const img=document.createElement('img');img.src='/api/ads/media/'+encodeURIComponent(creative.id)+'?preview=1';img.alt=creative.alt||'Banner xem trước';img.addEventListener('error',()=>{img.remove();const note=document.createElement('p');note.textContent='Chưa tải được banner xem trước.';el.append(note);},{once:true});el.append(img);}else{const note=document.createElement('p');note.textContent=fields?.type==='adsense'?'Vị trí Google AdSense · Không tải quảng cáo thật khi xem trước':'Chọn chiến dịch cho vị trí này';el.append(note);}applyAdSizing(el,el.querySelector('img')||el.querySelector('p'),placement||{},model.device);if(placement?.enabled===false)el.setAttribute('aria-description','Vị trí đang tắt');const choose=()=>{selected=id;stage.querySelectorAll('.ad-preview-zone').forEach(z=>z.classList.toggle('selected',z.dataset.adZone===id));send('ads-preview-zone',{zoneId:id});};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();choose();const campaignId=e.dataTransfer?.getData('text/plain');if(campaignId)send('ads-preview-zone',{zoneId:id,campaignId});};if(selected===id)el.classList.add('selected');return el;}
function mount(id,target,where='append'){if(target){const z=zone(id);if(where==='append')target.append(z);else if(where==='prepend')target.prepend(z);else target[where](z);}}
function render(){const page=pages[model.page]?model.page:'home';for(const name of ['privacy','about']){let link=document.querySelector('link[data-preview-info="'+name+'"]');if(!link){link=document.createElement('link');link.rel='stylesheet';link.href='/'+name+'.css';link.dataset.previewInfo=name;document.head.append(link);}link.disabled=page!=='info';}stage.className='ad-preview-stage '+(model.device==='mobile'?'mobile':'desktop');stage.replaceChildren();document.body.className=page==='home'||page==='how-it-works'?'onboarding':page==='explore'||page==='community'?'swipe-page':'';
 if(page==='home'||page==='how-it-works'){stage.innerHTML=landingHTML;initHowItWorks({Broke:()=>{},Bros:()=>{}});const welcome=stage.querySelector('#welcome'),hiw=stage.querySelector('#how-it-works');welcome.style.display=page==='home'?'flex':'none';hiw.style.display=page==='how-it-works'?'block':'none';if(page==='home'){mount('home-top',stage.querySelector('.welcome-content'),'before');mount('home-bottom',stage.querySelector('.welcome-hint'),'after');mount('footer-banner',stage.querySelector('.welcome-footer'),'before');}else{mount('how-it-works-banner',stage.querySelector('.hiw-trust'),'before');mount('footer-banner',stage.querySelector('.hiw-shell'));}}
 else if(page==='explore'||page==='community'){const card={name:'Câu chuyện minh họa',age:null,location:'Cộng đồng',photo:null,debts:[{title:'Một khởi đầu mới',amount:1000000,story:'Dữ liệu minh họa công khai dành cho xem trước bố cục.'}]};const post={id:'preview-public',amount:1000000,pledged:0,category:'Khác',sample:true};stage.innerHTML='<div class="main"><main><section class="content-grid"><section id="content"><div class="discover-layout">'+discoverIntro()+'<section class="discover-deck"><section class="swipe-stage">'+discoveryCard(card,{post,saved:false})+'</section></section>'+discoverCommunity({stories:0,saved:0})+'</div></section></section><footer>DebtFreeLately © 2026</footer></main></div>';if(page==='explore'){mount('explore-sidebar',stage.querySelector('.discover-community'),'prepend');mount('explore-content',stage.querySelector('.discover-deck'),'append');}mount('community-banner',stage.querySelector('.discover-community'));mount('footer-banner',stage.querySelector('footer'),'before');}
 else{stage.innerHTML=infoHTML;mount('footer-banner',stage.querySelector('main'));}
 stage.querySelectorAll('button:not(.ad-preview-zone),input,select,textarea').forEach(el=>{if(!el.closest('#how-it-works [role="tablist"]'))el.disabled=true;});stage.querySelectorAll('a').forEach(a=>{a.removeAttribute('href');a.setAttribute('aria-disabled','true');});}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==window.parent||event.data?.type!=='ads-preview-config'||!snapshot)return;const input=event.data;if(!pages[input.page]||!['desktop','mobile'].includes(input.device))return;model={placements:Array.isArray(input.placements)?input.placements:snapshot.placements?.draft?.zones||[],campaigns:Array.isArray(input.campaigns)?input.campaigns:snapshot.campaigns||[],creatives:Array.isArray(input.creatives)?input.creatives:snapshot.creatives||[],device:input.device,page:input.page};render();});
try{const response=await fetch('/api/admin/ads/preview',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error();const result=await response.json();if(!result.allowed)throw Error();snapshot=result.config;model={placements:snapshot.placements?.draft?.zones||[],campaigns:snapshot.campaigns||[],creatives:snapshot.creatives||[],device:'desktop',page:'home'};document.querySelector('.ad-preview-note').textContent='Xem trước bố cục · Không ghi lượt hiển thị hoặc lượt nhấp. Các thao tác riêng tư đã tắt.';render();send('ads-preview-ready');}catch{document.querySelector('.ad-preview-note').textContent='Bạn cần đăng nhập quản trị để xem trước quảng cáo.';}
